WITH base AS (SELECT id, customer_id, account_type, balance, status, UPPER(status) AS status_upper, COALESCE(status, 'OTHER') AS status_clean FROM accounts WHERE account_type IN ('LOAN', 'CREDIT', 'CHECKING')) SELECT CASE WHEN balance >= 65000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, customer_id, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, COUNT_IF(account_type = 'CHECKING') AS checking_events, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM base GROUP BY CASE WHEN balance >= 65000 THEN 'HIGH' ELSE 'LOW' END, customer_id;
